pearance.Button};bar.Controls.Add(edit);resources.Controls.Add(bar);resources.Controls.Add(new Label{AutoSize=true,Text="Les tags sont mis à jour au lancement du logiciel."});var tagsPanel=new FlowLayoutPanel{Width=740,Height=62,Visible=false};var common=new TextBox{Width=220};var specific=new TextBox{Width=260};var save=new Button{Text="Appliquer",AutoSize=true};tagsPanel.Controls.AddRange(new Control[]{new Label{Text="Communs au dossier",AutoSize=true},common,new Label{Text="Cette animation",AutoSize=true},specific,save});resources.Controls.Add(tagsPanel);Action load=()=>{var entry=files.SelectedItem as Entry;tagsPanel.Enabled=entry!=null&&!entry.Directory;if(!tagsPanel.Enabled)return;var map=FolderTagsR18.Read(Path.GetDirectoryName(entry.Path));string a,b;map.TryGetValue("communs",out a);map.TryGetValue(Path.GetFileName(entry.Path),out b);common.Text=a??"";specific.Text=b??(File.Exists(entry.Path+".tags.txt")?File.ReadAllText(entry.Path+".tags.txt"):"");};edit.CheckedChanged+=delegate{tagsPanel.Visible=edit.Checked;load();};files.SelectedIndexChanged+=delegate{if(edit.Checked)load();};save.Click+=delegate{var entry=files.SelectedItem as Entry;if(entry==null||entry.Directory)return;try{FolderTagsR18.Write(entry.Path,common.Text,specific.Text);status.Text="Tags enregistrés dans le tags.txt du dossier.";}catch(Exception ex){status.Text=ex.Message;}};}}
